import{_ as a,C as s,o as d,c as m,j as i,a as l,E as t,a3 as r}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"千字文 · 全篇","description":"《千字文》全篇一千字，按内容分八节，逐节给原文、引读与字词。","frontmatter":{"title":"千字文 · 全篇","description":"《千字文》全篇一千字，按内容分八节，逐节给原文、引读与字词。","category":"guide","aliases":["千字文","千字文全篇"],"source":["《千字文》（通行本）"]},"headers":[],"relativePath":"lizhimingde/qianziwen/chapter-01.md","filePath":"lizhimingde/qianziwen/chapter-01.md","lastUpdated":1789470132000}'),u={name:"lizhimingde/qianziwen/chapter-01.md"};function p(y,n,h,b,_,j){const o=s("DaoReadingPrelude"),g=s("DaoTextReading"),e=s("DaoKeywordCards");return d(),m("div",null,[n[0]||(n[0]=i("h1",{id:"千字文-·-全篇",tabindex:"-1"},[l("千字文 · 全篇 "),i("a",{class:"header-anchor",href:"#千字文-·-全篇","aria-label":'Permalink to "千字文 · 全篇"'},"​")],-1)),t(o,{title:"一千字里的中国：先通读，再八节细看",summary:"《千字文》四字一句、两句一韵，一千字不重不漏，本是为识字而编，却由识字铺开成一篇缩写的中国文化小百科：从天地开辟讲到日用起居，中间插入上古史、修身、人伦、都邑、史地与农政。这一页把全文按内容分为八节，每节都有原文、一句引读与该节字词。",points:[{label:"先读",text:"先顺着八节把原文通读一遍，遇到不认得的字不必停下。"},{label:"再辨",text:"留意它的走法：由天及地、由外及内、由史及身，一层层收到日用。"},{label:"后想",text:"读完之后再看：这一千字里，哪几句和你现在的日子有关。"}],hint:"竹简 / 经典两种读法可随时切换（切换后全页同步）；经典模式下点带底色的词可看释义。"}),n[1]||(n[1]=i("h2",{id:"jie-1",tabindex:"-1"},[l("一、天地自然 "),i("a",{class:"header-anchor",href:"#jie-1","aria-label":'Permalink to "一、天地自然 {#jie-1}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第一节原文：天地自然",paragraphs:["天地玄黄，宇宙洪荒。","日月盈昃，辰宿列张。","寒来暑往，秋收冬藏。","闰余成岁，律吕调阳。","云腾致雨，露结为霜。","金生丽水，玉出昆冈。","剑号巨阙，珠称夜光。","果珍李柰，菜重芥姜。","海咸河淡，鳞潜羽翔。"],"classic-groups":[{id:"tian",start:0,end:5,label:"天地日月"},{id:"wu",start:5,end:9,label:"金玉物产"}],glossary:[{id:"ze",term:"昃",pinyin:"zè",meaning:"日西斜。日月盈昃，说的是月由圆到缺、日由中天到西斜，都是运行。"},{id:"runyu",term:"闰余",pinyin:"rùn yú",meaning:"历法术语。一年实际日数比整数日多出零头，累积而成闰月；闰月与岁余相配，才成岁时。"},{id:"lvlv",term:"律吕",pinyin:"lǜ lǚ",meaning:"古乐十二音：六律为阳、六吕为阴。古人以十二律与十二月相应，用律管候气来调正节气。"},{id:"juque",term:"巨阙",pinyin:"jù què",meaning:"春秋时越王勾践所铸宝剑之名，与湛卢、纯钩等并称。"},{id:"yeguang",term:"夜光",pinyin:"yè guāng",meaning:"夜明珠。一说即隋侯之珠，夜里能发光。"},{id:"nai",term:"柰",pinyin:"nài",meaning:"柰树之果，形似苹果而小。果珍李柰，指果中珍品是李与柰。"}]}),n[2]||(n[2]=r("",3)),t(e,{items:[{term:"玄黄",pinyin:["xuán","huáng"],meaning:"天玄而地黄。语本《易·坤·文言》「夫玄黄者，天地之杂也，天玄而地黄」，指天地初成时的颜色。"},{term:"洪荒",pinyin:["hóng","huāng"],meaning:"广大荒远、浑沌未分的样子。宇指上下四方，宙指古往今来，「宇宙」合起来就是时间与空间。"},{term:"盈昃",pinyin:["yíng","zè"],meaning:"月圆为盈、日斜为昃。《易·丰》「日中则昃，月盈则食」讲的是同一个道理：到极处就要转。"},{term:"闰余成岁",pinyin:["rùn","yú","chéng","suì"],meaning:"置闰以成年。阴历一年约三百五十四日，与太阳年差约十一日，三年一闰、五年再闰，才不至于寒暑错位。"},{term:"律吕调阳",pinyin:["lǜ","lǚ","tiáo","yáng"],meaning:"以十二律对应十二月来调正节气。律为阳声、吕为阴声，古人候气于律管，观其应时而动。"},{term:"丽水",pinyin:["lì","shuǐ"],meaning:"古称金沙江为丽水，一说其地出金。「金生丽水」即金沙出于丽水。"},{term:"昆冈",pinyin:["kūn","gāng"],meaning:"昆仑山，古以为产玉之地。《尚书·胤征》有「火炎昆冈，玉石俱焚」之语。"},{term:"李柰芥姜",pinyin:["lǐ","nài","jiè","jiāng"],meaning:"李、柰是果中珍品，芥、姜是菜中要味。「菜重芥姜」的「重」是看重，不是分量重。"},{term:"鳞潜羽翔",pinyin:["lín","qián","yǔ","xiáng"],meaning:"鱼在水中潜、鸟在空中翔——由海河写到水陆众生，收束这一节的自然之景。"}]}),n[3]||(n[3]=i("h2",{id:"jie-2",tabindex:"-1"},[l("二、上古治世 "),i("a",{class:"header-anchor",href:"#jie-2","aria-label":'Permalink to "二、上古治世 {#jie-2}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第二节原文：上古治世",paragraphs:["龙师火帝，鸟官人皇。","始制文字，乃服衣裳。","推位让国，有虞陶唐。","吊民伐罪，周发殷汤。","坐朝问道，垂拱平章。","爱育黎首，臣伏戎羌。","遐迩一体，率宾归王。","鸣凤在竹，白驹食场。","化被草木，赖及万方。"],"classic-groups":[{id:"guan",start:0,end:2,label:"官制与文字"},{id:"rang",start:2,end:4,label:"禅让与征伐"},{id:"de",start:4,end:9,label:"治世与德化"}],glossary:[{id:"longshi",term:"龙师",pinyin:"lóng shī",meaning:"传说伏羲氏以龙名官，故称龙师，是上古以图腾纪官的标志。"},{id:"niaoguan",term:"鸟官",pinyin:"niǎo guān",meaning:"传说少昊氏以鸟名官，故称鸟官，与「龙师」对举。"},{id:"chuigong",term:"垂拱",pinyin:"chuí gǒng",meaning:"垂衣拱手。形容君主不必亲自操劳，天下自安。"},{id:"pingzhang",term:"平章",pinyin:"píng zhāng",meaning:"辨别彰明。语本《尚书·尧典》「平章百姓」，指辨明政事得失。"},{id:"lishou",term:"黎首",pinyin:"lí shǒu",meaning:"黎民百姓。黎是众多，首指人民。"},{id:"rongqiang",term:"戎羌",pinyin:"róng qiāng",meaning:"西戎与羌，泛指西部边地的部族。"},{id:"xiaer",term:"遐迩",pinyin:"xiá ěr",meaning:"远近。遐迩一体，指远近之地合为一体。"}]}),n[4]||(n[4]=r("",3)),t(e,{items:[{term:"龙师火帝",pinyin:["lóng","shī","huǒ","dì"],meaning:"伏羲氏以龙纪官，神农氏以火纪官。指上古以图腾、以火政命名官制的传说时代。"},{term:"鸟官人皇",pinyin:["niǎo","guān","rén","huáng"],meaning:"少昊氏以鸟名官，人皇氏为传说中三皇之一。连上句，泛指三皇五帝之世。"},{term:"始制文字",pinyin:["shǐ","zhì","wén","zì"],meaning:"传说黄帝之史仓颉造字。有了文字，政令与经验才可传之久远。"},{term:"乃服衣裳",pinyin:["nǎi","fú","yī","shang"],meaning:"传说黄帝制衣裳、嫘祖养蚕。自此有了服制，人别于禽兽。"},{term:"推位让国",pinyin:["tuī","wèi","ràng","guó"],meaning:"禅让：尧让位于舜、舜让位于禹，不传子而传贤。"},{term:"有虞陶唐",pinyin:["yǒu","yú","táo","táng"],meaning:"有虞氏指舜，陶唐氏指尧。以氏号代称两位古帝。"},{term:"吊民伐罪",pinyin:["diào","mín","fá","zuì"],meaning:"抚慰百姓、讨伐暴君。周发指周武王姬发，殷汤指商汤，指汤伐桀、武伐纣。"},{term:"垂拱平章",pinyin:["chuí","gǒng","píng","zhāng"],meaning:"垂衣拱手而天下治，同时辨明政事得失。无为不是不问事，是先把人和制度立好。"},{term:"鸣凤在竹",pinyin:["míng","fèng","zài","zhú"],meaning:"凤凰鸣于竹间、白马食于场圃，古人以为德政所致之祥瑞。二句是「化被草木」的图景。"}]}),n[5]||(n[5]=i("h2",{id:"jie-3",tabindex:"-1"},[l("三、修身之本 "),i("a",{class:"header-anchor",href:"#jie-3","aria-label":'Permalink to "三、修身之本 {#jie-3}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第三节原文：修身之本",paragraphs:["盖此身发，四大五常。","恭惟鞠养，岂敢毁伤。","女慕贞洁，男效才良。","知过必改，得能莫忘。","罔谈彼短，靡恃己长。","信使可覆，器欲难量。","墨悲丝染，诗赞羔羊。","景行维贤，克念作圣。","德建名立，形端表正。","空谷传声，虚堂习听。","祸因恶积，福缘善庆。","尺璧非宝，寸阴是竞。"],"classic-groups":[{id:"shen",start:0,end:2,label:"身体发肤"},{id:"yan",start:2,end:6,label:"言行与改过"},{id:"de",start:6,end:9,label:"德行与教化"},{id:"xi",start:9,end:12,label:"因果与惜时"}],glossary:[{id:"sida",term:"四大",pinyin:"sì dà",meaning:"古印度用以说明身体的四种元素：地、水、火、风。此处与「五常」（仁义礼智信）并举——一说身、一说德。"},{id:"juyang",term:"鞠养",pinyin:"jū yǎng",meaning:"养育。恭惟鞠养，是恭敬地念及父母养育之劳。"},{id:"wang",term:"罔",pinyin:"wǎng",meaning:"不要。罔谈彼短，即不要议论别人的短处。"},{id:"mi",term:"靡",pinyin:"mǐ",meaning:"不要。靡恃己长，即不要倚仗自己的长处。"},{id:"fu",term:"覆",pinyin:"fù",meaning:"核对、验察。信使可覆，指说出口的话要经得起反复核对。"},{id:"jingxing",term:"景行",pinyin:"jǐng xíng",meaning:"大道、光明的德行。语本《诗经·小雅》「高山仰止，景行行止」。"},{id:"chibi",term:"尺璧",pinyin:"chǐ bì",meaning:"直径一尺的美玉，喻贵重之物。尺璧非宝、寸阴是竞——美玉不算宝，光阴才要争。"}]}),n[6]||(n[6]=r("",3)),t(e,{items:[{term:"盖此身发",pinyin:["gài","cǐ","shēn","fà"],meaning:"语本《孝经》「身体发肤，受之父母，不敢毁伤，孝之始也」。盖是发语词，这一节由此起。"},{term:"四大五常",pinyin:["sì","dà","wǔ","cháng"],meaning:"四大为地水火风，五常为仁义礼智信。一句里把「身」与「德」两样根基一起立住。"},{term:"恭惟鞠养",pinyin:["gōng","wéi","jū","yǎng"],meaning:"恭敬地想父母抚育之劳；由此才有「岂敢毁伤」——不敢轻慢这具受之父母的身体。"},{term:"墨悲丝染",pinyin:["mò","bēi","sī","rǎn"],meaning:"《墨子·所染》载墨子见染丝而悲：丝入青则青、入黄则黄，一染便难复白。喻人所处所习，熏染最要紧。"},{term:"诗赞羔羊",pinyin:["shī","zàn","gāo","yáng"],meaning:"《诗经·召南·羔羊》以「羔羊之皮，素丝五紽」称美在位者节俭正直。"},{term:"景行维贤",pinyin:["jǐng","xíng","wéi","xián"],meaning:"效法大道上的贤者。「维」是维系、依循。"},{term:"克念作圣",pinyin:["kè","niàn","zuò","shèng"],meaning:"能克制杂念、念念守正，就可以作圣人。语本《尚书·多方》「惟圣罔念作狂，惟狂克念作圣」。"},{term:"空谷传声",pinyin:["kōng","gǔ","chuán","shēng"],meaning:"空谷里喊一声，回响清楚；虚堂之中，声音易听。喻心空则能受、能察。"},{term:"尺璧寸阴",pinyin:["chǐ","bì","cùn","yīn"],meaning:"语本《淮南子》「圣人不贵尺之璧而重寸之阴」。一尺美玉不算宝，一寸光阴才值得去争。"}]}),n[7]||(n[7]=i("h2",{id:"jie-4",tabindex:"-1"},[l("四、人伦持守 "),i("a",{class:"header-anchor",href:"#jie-4","aria-label":'Permalink to "四、人伦持守 {#jie-4}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第四节原文：人伦持守",paragraphs:["资父事君，曰严与敬。","孝当竭力，忠则尽命。","临深履薄，夙兴温凊。","似兰斯馨，如松之盛。","川流不息，渊澄取映。","容止若思，言辞安定。","笃初诚美，慎终宜令。","荣业所基，籍甚无竟。","学优登仕，摄职从政。","存以甘棠，去而益咏。","乐殊贵贱，礼别尊卑。","上和下睦，夫唱妇随。","外受傅训，入奉母仪。","诸姑伯叔，犹子比儿。","孔怀兄弟，同气连枝。","交友投分，切磨箴规。","仁慈隐恻，造次弗离。","节义廉退，颠沛匪亏。","性静情逸，心动神疲。","守真志满，逐物意移。","坚持雅操，好爵自縻。"],"classic-groups":[{id:"qin",start:0,end:5,label:"事亲事君"},{id:"yi",start:5,end:9,label:"仪态与立身"},{id:"shi",start:9,end:12,label:"出仕与礼序"},{id:"jia",start:12,end:16,label:"家世人伦"},{id:"jiao",start:16,end:21,label:"交友与性情"}],glossary:[{id:"wenqing",term:"温凊",pinyin:"wēn qìng",meaning:"让父母冬暖夏凉。凊读 qìng，是凉爽。语本《礼记·曲礼》「冬温而夏凊，昏定而晨省」。"},{id:"yuancheng",term:"渊澄",pinyin:"yuān chéng",meaning:"深潭澄清。渊澄取映，指水静而清，可以照见物影——喻心清可鉴。"},{id:"jishen",term:"籍甚",pinyin:"jí shèn",meaning:"声名盛大、籍籍有名。籍甚无竟，指声誉传之不尽。"},{id:"gantang",term:"甘棠",pinyin:"gān táng",meaning:"周召伯巡行听政，曾在甘棠树下，后人思其德而爱其树，作《召南·甘棠》。存以甘棠、去而益咏，指在位有惠政，离去后更被怀念。"},{id:"fuxun",term:"傅训",pinyin:"fù xùn",meaning:"师傅的训导。外受傅训、入奉母仪——在外受师训，在家奉母教。"},{id:"youzi",term:"犹子",pinyin:"yóu zǐ",meaning:"侄子。诸姑伯叔、犹子比儿，是说对姑叔而言，侄子就如自己的孩子。"},{id:"konghuai",term:"孔怀",pinyin:"kǒng huái",meaning:"格外怀念。语本《诗经·小雅·常棣》「兄弟孔怀」，后以「孔怀」代指兄弟。"},{id:"qiemo",term:"切磨箴规",pinyin:"qiē mó zhēn guī",meaning:"切磋琢磨、规劝告诫——朋友之间相互砥砺。「切磨」出自《诗经》「如切如磋，如琢如磨」。"}]}),n[8]||(n[8]=r("",3)),t(e,{items:[{term:"资父事君",pinyin:["zī","fù","shì","jūn"],meaning:"以事父之道事君。语本《孝经》「资于事父以事君，而敬同」。严与敬，是这一节的总纲。"},{term:"临深履薄",pinyin:["lín","shēn","lǚ","bó"],meaning:"如临深渊、如履薄冰。语出《诗经·小雅·小旻》，形容存心戒慎。"},{term:"夙兴温凊",pinyin:["sù","xīng","wēn","qìng"],meaning:"早起操持，冬使父母温、夏使父母凉。是「孝当竭力」落到日常的样子。"},{term:"川流不息",pinyin:["chuān","liú","bù","xī"],meaning:"如河水奔流不止，如深潭澄澈可照——一喻德泽绵长，一喻心境清明。"},{term:"笃初慎终",pinyin:["dǔ","chū","shèn","zhōng"],meaning:"开头诚恳固然好，能慎重收尾更难。《诗经》「靡不有初，鲜克有终」说的是同一件事。"},{term:"学优登仕",pinyin:["xué","yōu","dēng","shì"],meaning:"学有余力便出仕任事。语本《论语》「学而优则仕」；摄职从政，是代理职事、参与政务。"},{term:"甘棠遗爱",pinyin:["gān","táng","yí","ài"],meaning:"召伯听政于甘棠树下，去后民思其人而爱其树。后世以「甘棠遗爱」称颂离任后仍被怀念的惠政。"},{term:"孔怀同气",pinyin:["kǒng","huái","tóng","qì"],meaning:"兄弟最为相念，同气连枝如一棵树上的枝干，血脉同源。"},{term:"好爵自縻",pinyin:["hǎo","jué","zì","mí"],meaning:"美好的爵位会自己系到身上。「縻」是系、拴。内守雅操，外来的名位反而不必去求。"}]}),n[9]||(n[9]=i("h2",{id:"jie-5",tabindex:"-1"},[l("五、都邑典籍 "),i("a",{class:"header-anchor",href:"#jie-5","aria-label":'Permalink to "五、都邑典籍 {#jie-5}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第五节原文：都邑典籍",paragraphs:["都邑华夏，东西二京。","背邙面洛，浮渭据泾。","宫殿盘郁，楼观飞惊。","图写禽兽，画彩仙灵。","丙舍旁启，甲帐对楹。","肆筵设席，鼓瑟吹笙。","升阶纳陛，弁转疑星。","右通广内，左达承明。","既集坟典，亦聚群英。","杜稿钟隶，漆书壁经。","府罗将相，路侠槐卿。","户封八县，家给千兵。","高冠陪辇，驱毂振缨。","世禄侈富，车驾肥轻。","策功茂实，勒碑刻铭。"],"classic-groups":[{id:"jing",start:0,end:4,label:"两京形胜"},{id:"gong",start:4,end:7,label:"宫室陈设"},{id:"dian",start:7,end:10,label:"典籍与贤才"},{id:"jiang",start:10,end:15,label:"将相世禄"}],glossary:[{id:"erjing",term:"二京",pinyin:"èr jīng",meaning:"西京长安与东京洛阳。汉唐皆两京并置，故称东西二京。"},{id:"mang",term:"邙",pinyin:"máng",meaning:"北邙山，在洛阳之北。背邙面洛，写洛阳背山面水的地势；浮渭据泾，写长安倚渭水、据泾水。"},{id:"jiazhang",term:"甲帐",pinyin:"jiǎ zhàng",meaning:"华美的帐幕。丙舍是宫中别室，甲帐对楹写宫室内外陈设之盛。"},{id:"bian",term:"弁",pinyin:"biàn",meaning:"古代男子加冠时所用的一种帽子。弁转疑星，写朝会时冠饰转动如星。"},{id:"guangnei",term:"广内",pinyin:"guǎng nèi",meaning:"汉宫广内殿，为收藏秘书之所；承明殿则是贤士待诏之处。一藏典籍、一聚贤才。"},{id:"fendian",term:"坟典",pinyin:"fén diǎn",meaning:"三坟、五典，传说中上古典籍之名，后泛指古书。"},{id:"dugao",term:"杜稿钟隶",pinyin:"dù gǎo zhōng lì",meaning:"杜度的章草稿书、钟繇的隶书，都是书法名迹；漆书是先人以漆书写的古书，壁经指自孔子旧宅壁中所得之经。"},{id:"huaiqing",term:"槐卿",pinyin:"huái qīng",meaning:"周代朝廷植三槐，三公位其下，故以槐卿称三公九卿。路侠槐卿，写重臣夹道而立。"}]}),n[10]||(n[10]=r("",3)),t(e,{items:[{term:"东西二京",pinyin:["dōng","xī","èr","jīng"],meaning:"洛阳为东京、长安为西京。华夏是中国的旧称——这一句把「都城」放到天下的尺度上说。"},{term:"背邙面洛",pinyin:["bèi","máng","miàn","luò"],meaning:"洛阳背靠北邙山、面朝洛水；长安则渭水环绕、泾水为据。两句写形胜，也写择都之理。"},{term:"宫殿盘郁",pinyin:["gōng","diàn","pán","yù"],meaning:"宫殿曲折深远、层层叠叠，楼观高峻欲飞，望之令人惊。"},{term:"丙舍甲帐",pinyin:["bǐng","shè","jiǎ","zhàng"],meaning:"别室在旁开启，华帐对着厅柱。写宫室的陈设排布。"},{term:"弁转疑星",pinyin:["biàn","zhuǎn","yí","xīng"],meaning:"登阶入殿时冠饰转动，望去像一片星。写朝会仪容之盛。"},{term:"广内承明",pinyin:["guǎng","nèi","chéng","míng"],meaning:"广内殿藏书，承明殿待士。右通、左达两语，把宫室与文事连在一起。"},{term:"杜稿钟隶",pinyin:["dù","gǎo","zhōng","lì"],meaning:"杜度的章草、钟繇的隶书，与漆书、壁经并举——写典籍与书法之富。"},{term:"路侠槐卿",pinyin:["lù","xiá","huái","qīng"],meaning:"府中罗列将相，路上夹道而立的是三公九卿。「侠」通「夹」。"},{term:"勒碑刻铭",pinyin:["lè","bēi","kè","míng"],meaning:"把功劳刻在碑石与铭器上。策功茂实、勒碑刻铭，是这一节写功业的落点。"}]}),n[11]||(n[11]=i("h2",{id:"jie-6",tabindex:"-1"},[l("六、史地农政 "),i("a",{class:"header-anchor",href:"#jie-6","aria-label":'Permalink to "六、史地农政 {#jie-6}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第六节原文：史地农政",paragraphs:["磻溪伊尹，佐时阿衡。","奄宅曲阜，微旦孰营。","桓公匡合，济弱扶倾。","绮回汉惠，说感武丁。","俊乂密勿，多士寔宁。","晋楚更霸，赵魏困横。","假途灭虢，践土会盟。","何遵约法，韩弊烦刑。","起翦颇牧，用军最精。","宣威沙漠，驰誉丹青。","九州禹迹，百郡秦并。","岳宗泰岱，禅主云亭。","雁门紫塞，鸡田赤城。","昆池碣石，钜野洞庭。","旷远绵邈，岩岫杳冥。","治本于农，务兹稼穑。","俶载南亩，我艺黍稷。","税熟贡新，劝赏黜陟。"],"classic-groups":[{id:"xian",start:0,end:4,label:"贤相辅时"},{id:"ba",start:4,end:8,label:"士人与霸业"},{id:"jiang",start:8,end:12,label:"名将与疆域"},{id:"shan",start:12,end:15,label:"山川边塞"},{id:"nong",start:15,end:18,label:"农政为本"}],glossary:[{id:"panxi",term:"磻溪",pinyin:"pán xī",meaning:"相传姜太公垂钓之处，在今陕西宝鸡一带。此处以「磻溪」代指姜太公。"},{id:"aheng",term:"阿衡",pinyin:"ā héng",meaning:"伊尹的官号、尊称。伊尹辅商汤而兴，是贤相的代称。"},{id:"fuyue",term:"说感武丁",pinyin:"yuè gǎn wǔ dīng",meaning:"殷高宗武丁梦得贤人，求得傅说为相，殷道复兴。「说」指傅说，读 yuè。"},{id:"jiaguo",term:"假途灭虢",pinyin:"jiǎ tú miè guó",meaning:"晋献公向虞国借道伐虢，回师时顺手灭虞。后世以「假途灭虢」喻借路为名、兼并其实。"},{id:"jiasi",term:"稼穑",pinyin:"jià sè",meaning:"种曰稼、收曰穑，合指农事。治本于农、务兹稼穑，是这一节的落脚。"},{id:"taidai",term:"泰岱",pinyin:"tài dài",meaning:"泰山。五岳以泰山为宗；禅主云亭，指古帝封禅多在云云山、亭亭山。"},{id:"chuzhi",term:"黜陟",pinyin:"chù zhì",meaning:"贬降与晋升。税熟贡新之后，以劝赏黜陟考核官吏——农政与吏治相连。"}]}),n[12]||(n[12]=r("",3)),t(e,{items:[{term:"磻溪伊尹",pinyin:["pán","xī","yī","yǐn"],meaning:"姜太公钓于磻溪而佐周，伊尹耕于有莘之野而佐商。两个「待时而动」的贤相。"},{term:"奄宅曲阜",pinyin:["yǎn","zhái","qū","fù"],meaning:"周公旦受封于曲阜（鲁国）；微旦孰营——若没有周公，谁来经营周室的基业。"},{term:"桓公匡合",pinyin:["huán","gōng","kuāng","hé"],meaning:"齐桓公九合诸侯、匡正天下，济弱扶倾：扶助弱小、援救倾危。"},{term:"绮回汉惠",pinyin:["qǐ","huí","hàn","huì"],meaning:"商山四皓中的绮里季出山，使刘邦打消废太子之念，保住了后来的汉惠帝。"},{term:"俊乂密勿",pinyin:["jùn","yì","mì","wù"],meaning:"俊乂指才德出众之士，密勿是勤勉用事。多士寔宁：人才众而国乃安。"},{term:"约法烦刑",pinyin:["yuē","fǎ","fán","xíng"],meaning:"萧何依刘邦「约法三章」而定汉律，律简而得人心；韩非之说主张严刑繁法，反受其弊。一句对照，讲的是法与治的分寸。"},{term:"起翦颇牧",pinyin:["qǐ","jiǎn","pō","mù"],meaning:"白起、王翦、廉颇、李牧——战国四位最善用兵的名将。"},{term:"驰誉丹青",pinyin:["chí","yù","dān","qīng"],meaning:"名声流传于图画之中。汉宣帝曾画功臣像于麒麟阁，后世以「丹青」代指功名图画。"},{term:"九州禹迹",pinyin:["jiǔ","zhōu","yǔ","jì"],meaning:"九州是禹治水后所划的天下区划，百郡是秦统一后所置之郡——疆域的两次定型。"}]}),n[13]||(n[13]=i("h2",{id:"jie-7",tabindex:"-1"},[l("七、为政隐逸 "),i("a",{class:"header-anchor",href:"#jie-7","aria-label":'Permalink to "七、为政隐逸 {#jie-7}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第七节原文：为政隐逸",paragraphs:["孟轲敦素，史鱼秉直。","庶几中庸，劳谦谨敕。","聆音察理，鉴貌辨色。","贻厥嘉猷，勉其祗植。","省躬讥诫，宠增抗极。","殆辱近耻，林皋幸即。","两疏见机，解组谁逼。","索居闲处，沉默寂寥。","求古寻论，散虑逍遥。","欣奏累遣，戚谢欢招。","渠荷的历，园莽抽条。","枇杷晚翠，梧桐早凋。","陈根委翳，落叶飘摇。","游鹍独运，凌摩绛霄。","耽读玩市，寓目囊箱。","易輶攸畏，属耳垣墙。","具膳餐饭，适口充肠。","饱饫烹宰，饥厌糟糠。","亲戚故旧，老少异粮。","妾御绩纺，侍巾帷房。","纨扇圆絜，银烛炜煌。"],"classic-groups":[{id:"cao",start:0,end:6,label:"在朝的操守"},{id:"tui",start:6,end:10,label:"见机而退"},{id:"shi",start:10,end:14,label:"草木时节"},{id:"du",start:14,end:16,label:"读书与警惕"},{id:"ri",start:16,end:21,label:"日用起居"}],glossary:[{id:"yijue",term:"贻厥嘉猷",pinyin:"yí jué jiā yóu",meaning:"留下好的谋略给后人。语本《诗经·大雅》「贻厥孙谋」；勉其祗植，是勉励后人恭敬培植。"},{id:"lingao",term:"林皋",pinyin:"lín gāo",meaning:"山林水边。殆辱近耻、林皋幸即——临近羞辱耻辱时，幸好还可以退到林泉。"},{id:"jiezhu",term:"解组",pinyin:"jiě zǔ",meaning:"解下印绶，即辞官。两疏见机、解组谁逼：汉疏广、疏受叔侄功成身退，不是被人逼走的。"},{id:"dili",term:"的历",pinyin:"dì lì",meaning:"鲜明、明净的样子。渠荷的历，写池中荷花的鲜亮。"},{id:"weiyi",term:"委翳",pinyin:"wěi yì",meaning:"枯倒而相互掩蔽。陈根委翳、落叶飘摇，写草木由盛而衰的时节。"},{id:"jiangxiao",term:"绛霄",pinyin:"jiàng xiāo",meaning:"红色的云霄。游鹍独运、凌摩绛霄，写大鸟独飞直上。"},{id:"yiyou",term:"易輶",pinyin:"yì yóu",meaning:"易是轻忽、輶是轻。易輶攸畏，指轻忽轻易之事最可畏；下句属耳垣墙，即隔墙有耳。"},{id:"zaokang",term:"糟糠",pinyin:"zāo kāng",meaning:"酒糟与米糠，指粗劣的食物。饱饫烹宰、饥厌糟糠，写饱时与饥时对食物的两种态度。"}]}),n[14]||(n[14]=r("",3)),t(e,{items:[{term:"孟轲敦素",pinyin:["mèng","kē","dūn","sù"],meaning:"孟轲即孟子，敦素是笃厚朴素；史鱼是卫国大夫，以刚直著称。一动一静，是两种「直」。"},{term:"庶几中庸",pinyin:["shù","jī","zhōng","yōng"],meaning:"力求合乎中庸，勤劳谦逊、谨慎自戒。「劳谦」出《易·谦》「劳谦君子，有终吉」。"},{term:"聆音察理",pinyin:["líng","yīn","chá","lǐ"],meaning:"听声音以辨情理，看容貌以别神色——审事察人的细功夫。"},{term:"省躬讥诫",pinyin:["xǐng","gōng","jī","jiè"],meaning:"反省自身、接纳讥诫。宠增抗极：恩宠越盛，越要防备「至极则反」。"},{term:"两疏见机",pinyin:["liǎng","shū","jiàn","jī"],meaning:"汉宣帝时疏广、疏受叔侄并为太子师傅，位高而主动请退，归乡以寿终。见机，是看见那个「该退」的时机。"},{term:"散虑逍遥",pinyin:["sàn","lǜ","xiāo","yáo"],meaning:"排遣忧虑而得自在。求古寻论、散虑逍遥，写退居后的日常：读书、论古、散心。"},{term:"耽读玩市",pinyin:["dān","dú","wán","shì"],meaning:"耽溺读书、玩味于市。后汉王充家贫无书，常游洛阳书肆，读所卖之书一见即能诵——用其事。"},{term:"属耳垣墙",pinyin:["zhǔ","ěr","yuán","qiáng"],meaning:"隔墙有耳。语本《诗经·小雅》「君子无易由言，耳属于垣」——说话轻易，最该提防。"},{term:"纨扇银烛",pinyin:["wán","shàn","yín","zhú"],meaning:"绢制团扇圆而洁净，银烛光辉明亮（炜煌）。写居处器物之清雅，与上一节的宫室之盛恰成对照。"}]}),n[15]||(n[15]=i("h2",{id:"jie-8",tabindex:"-1"},[l("八、起居收束 "),i("a",{class:"header-anchor",href:"#jie-8","aria-label":'Permalink to "八、起居收束 {#jie-8}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第八节原文：起居收束",paragraphs:["昼眠夕寐，蓝笋象床。","弦歌酒宴，接杯举觞。","矫手顿足，悦豫且康。","嫡后嗣续，祭祀烝尝。","稽颡再拜，悚惧恐惶。","笺牒简要，顾答审详。","骸垢想浴，执热愿凉。","驴骡犊特，骇跃超骧。","诛斩贼盗，捕获叛亡。","布射僚丸，嵇琴阮啸。","恬笔伦纸，钧巧任钓。","释纷利俗，并皆佳妙。","毛施淑姿，工颦妍笑。","年矢每催，曦晖朗曜。","璇玑悬斡，晦魄环照。","指薪修祜，永绥吉劭。","矩步引领，俯仰廊庙。","束带矜庄，徘徊瞻眺。","孤陋寡闻，愚蒙等诮。","谓语助者，焉哉乎也。"],"classic-groups":[{id:"qi",start:0,end:3,label:"起居宴乐"},{id:"ji",start:3,end:6,label:"祭祀与书牒"},{id:"chang",start:6,end:9,label:"常情与除害"},{id:"jiyi",start:9,end:12,label:"技艺之妙"},{id:"tian",start:12,end:15,label:"美人与天时"},{id:"shou",start:15,end:20,label:"祝愿与收束"}],glossary:[{id:"zhengchang",term:"烝尝",pinyin:"zhēng cháng",meaning:"冬祭曰烝、秋祭曰尝，合指四时祭祀。嫡后嗣续、祭祀烝尝，写的是血脉与礼的两重延续。"},{id:"qisang",term:"稽颡",pinyin:"qǐ sǎng",meaning:"叩头，以额触地。稽颡再拜、悚惧恐惶，写祭祖时的恭敬与敬畏。"},{id:"jiandie",term:"笺牒",pinyin:"jiān dié",meaning:"书信与文牒。笺牒简要、顾答审详——写出去的从简，答回来的要详。"},{id:"chaoxiang",term:"超骧",pinyin:"chāo xiāng",meaning:"骧是马昂首奔腾。骇跃超骧，写驴骡犊特受惊后腾跃奔驰之状。"},{id:"xuanji",term:"璇玑",pinyin:"xuán jī",meaning:"北斗七星中可转动的部分，也指浑天仪一类测天之物。璇玑悬斡、晦魄环照，写星辰运转、月魄明晦循环。"},{id:"zhixin",term:"指薪修祜",pinyin:"zhǐ xīn xiū hù",meaning:"语本《庄子·养生主》「指穷于为薪，火传也，不知其尽也」——柴有尽而火相传。修祜是修福，永绥吉劭是愿长久安宁吉祥。"},{id:"shudai",term:"束带矜庄",pinyin:"shù dài jīn zhuāng",meaning:"整束衣带、端庄自持。矩步引领、俯仰廊庙、束带矜庄、徘徊瞻眺，连写四种在朝廷进退顾盼的仪态。"}]}),n[16]||(n[16]=r("",3)),t(e,{items:[{term:"蓝笋象床",pinyin:["lán","sǔn","xiàng","chuáng"],meaning:"蓝笋是竹席，象床是象牙装饰之床。昼眠夕寐、蓝笋象床，写居处安适——这是全书由大及小收拢的第一步。"},{term:"弦歌酒宴",pinyin:["xián","gē","jiǔ","yàn"],meaning:"弦歌设宴、接杯举觞；矫手顿足，悦豫且康——写宴饮之乐，手足起舞而身心安和。"},{term:"稽颡再拜",pinyin:["qǐ","sǎng","zài","bài"],meaning:"叩头再拜、心怀敬畏。这一句与前面的「弦歌酒宴」相接，是古人生活里乐与敬的两面。"},{term:"骸垢想浴",pinyin:["hái","gòu","xiǎng","yù"],meaning:"身上有垢便想沐浴，手里执热便愿清凉——写人情之常。古人以这类「人之常情」收束日用之事。"},{term:"布射僚丸",pinyin:["bù","shè","liáo","wán"],meaning:"吕布射戟以解刘备之围，宜僚弄丸而使楚宋之兵不战——一武一技，都能排解纷争。"},{term:"嵇琴阮啸",pinyin:["jī","qín","ruǎn","xiào"],meaning:"嵇康善琴、阮籍长啸，是魏晋名士的两种自处方式。"},{term:"恬笔伦纸",pinyin:["tián","bǐ","lún","zhǐ"],meaning:"相传蒙恬改良毛笔、蔡伦改进造纸。钧巧任钓：马钧之巧、任公子之钓。四句连写技艺与器物。"},{term:"毛施淑姿",pinyin:["máo","shī","shū","zī"],meaning:"毛嫱（一说毛嫱为越地美姬）与西施，姿容美好；工颦妍笑，指善颦与美笑皆成妍态。"},{term:"谓语助者",pinyin:["wèi","yǔ","zhù","zhě"],meaning:"末句以「焉、哉、乎、也」四个语助词收尾。全文一千字不重不漏，最后落在四个虚字上，反倒最见巧思。"}]}),n[17]||(n[17]=r("",14))])}const q=a(u,[["render",p]]);export{x as __pageData,q as default};
